args.content:
SELECT ?item ?itemLabel ?lat ?long
WHERE {
  ?item p31/wdt:P31* wd:Q15472789.  # instance of 'point of interest'
  ?item wdt:P625 ?coord.  # coordinates
  ?item skos:label ?itemLabel.  # label
  ?coord wdt:P625 ?lat ?long.  # extract latitude and longitude
  FILTER (
    ?item wdt:P625 ?coord .
    BIND(
      IF(BOUND(?coord), ?coord, wd:Q8813) AS ?target
    )
  )
}

